export const refreshCatalogResponseSummaryOneAddedItemProviderRegExp = new RegExp('^[a-z0-9_-]{1,64}$');
export const refreshCatalogResponseSummaryOneRetiredItemProviderRegExp = new RegExp('^[a-z0-9_-]{1,64}$');
